#include <vector>
#include <algorithm>

class Solution {
public:
    int minIntervalsToCover(std::vector<std::vector<int>>& clips, int target_start, int target_end) {
        std::sort(clips.begin(), clips.end(), [](auto const& a, auto const& b) {
            if (a[0] != b[0]) return a[0] < b[0];
            return a[1] > b[1];
        });

        int count = 0, curr_end = target_start, farthest = target_start;
        int i = 0, n = clips.size();

        while (curr_end < target_end) {
            while (i < n && clips[i][0] <= curr_end) {
                farthest = std::max(farthest, clips[i][1]);
                i++;
            }
            if (farthest == curr_end) return -1;
            curr_end = farthest;
            count++;
        }
        return count;
    }
};

import java.util.*;

class Solution {
    public int minIntervalsToCover(int[][] clips, int targetStart, int targetEnd) {
        Arrays.sort(clips, (a, b) -> {
            if (a[0] != b[0]) return Integer.compare(a[0], b[0]);
            return Integer.compare(b[1], a[1]);
        });

        int count = 0, currEnd = targetStart, farthest = targetStart;
        int i = 0, n = clips.length;

        while (currEnd < targetEnd) {
            while (i < n && clips[i][0] <= currEnd) {
                farthest = Math.max(farthest, clips[i][1]);
                i++;
            }
            if (farthest == currEnd) return -1;
            currEnd = farthest;
            count++;
        }
        return count;
    }
}

